// Writes src/contracts/hubNumber.generated.ts: the Hub's phone number, taken from the number with id "hub" in
// data/catalogue/numbers.json, the one place the Hub's number is kept (AD-11). The resident app shows it where the
// directory cannot help (S02.06) and dials it from there, so the phone has it without asking the server.
//
//   node scripts/gen-hub-number.mjs           writes the generated file
//   node scripts/gen-hub-number.mjs --check   fails if the file differs from what numbers.json gives (npm test runs it)
//
// numbers.json writes the number as the Hub reads it, "(416) 421-8997"; the generated file stores it as E.164
// ("+14164218997", what tel: links take) and the app formats it for reading with displayPhone (src/contracts/phone.ts).
import { existsSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const SOURCE = "data/catalogue/numbers.json";
export const OUTPUT = "src/contracts/hubNumber.generated.ts";
export const HUB_ID = "hub";

const HEADER = `// GENERATED by scripts/gen-hub-number.mjs from ${SOURCE} (the number with id "${HUB_ID}"). Do not edit; run \`npm run gen:hub-number\`.`;

/** A ten-digit North American number, written any common way ("(416) 421-8997", "416-421-8997", "+1 416 421 8997"), as E.164. */
export function toE164(written) {
  let digits = String(written ?? "").replace(/\D/g, "");
  if (digits.length === 11 && digits[0] === "1") digits = digits.slice(1);
  if (digits.length !== 10) throw new Error(`${SOURCE}: the number with id "${HUB_ID}" is not a ten-digit North American number: ${JSON.stringify(written)}`);
  return `+1${digits}`;
}

/** The content of the generated file. Throws when numbers.json has no usable "hub" number. */
export function generate(root) {
  const file = JSON.parse(readFileSync(path.join(root, SOURCE), "utf8"));
  const hub = (file.numbers ?? []).find((entry) => entry.id === HUB_ID);
  if (!hub) throw new Error(`${SOURCE} has no number with id "${HUB_ID}"`);
  return `${HEADER}\n\n/** The Hub's number in E.164, the form a tel: link takes. Show it with displayPhone (phone.ts). */\nexport const HUB_PHONE_E164 = ${JSON.stringify(toE164(hub.number))};\n`;
}

function main(argv) {
  const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
  const content = generate(root);
  if (argv.includes("--check")) {
    if (!existsSync(path.join(root, OUTPUT)) || readFileSync(path.join(root, OUTPUT), "utf8") !== content) {
      console.error(`${OUTPUT} is stale; run "npm run gen:hub-number" and commit the result`);
      return 1;
    }
    console.log(`${OUTPUT} is up to date.`);
    return 0;
  }
  writeFileSync(path.join(root, OUTPUT), content);
  console.log(`Wrote ${OUTPUT}`);
  return 0;
}

// Run directly, not imported. Node runs the entry point by its real path (import.meta.url), while argv[1] keeps any
// symlink in the path it was given (macOS's /var is /private/var), so the two are compared as real paths.
if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href) process.exitCode = main(process.argv.slice(2));
